1: /**
2:  * dsh-token-guard —— 零依赖本地插件（与 dsh-mcp-gateway / dsh-agent-guard 同约束：
3:  * 装在 profile 之外，**不 import `@deepseek-ai/*`**，否则 profile 外解析不到）。
4:  *
5:  * 缺口：dsh-spill-policy 在 tools/post-execute 逐次裁剪大结果，但**显式跳过 read**
6:  * （`exec.name === "read"`），而 read 单次默认最多返回 50KB(≈12.5k token)——这些
7:  * 大 read 结果每一轮都随历史重发，是「消息占 ~81% 上下文」的主要来源之一。
8:  *
9:  * 本插件补上这块：对 read（以及配置的额外工具）的大结果，在**执行期**做头尾裁剪
10:  * + 自动落盘（复用 ctx.get("spillStore")），返回裁剪版 + 可回读路径。不改写非文本块，
11:  * 任一步失败都保留原文，绝不阻断工具。
12:  *
13:  * 与现有插件分工：
14:  *   - spill-policy      : 非 read 的大结果，>maxInlineTokens 落盘；
15:  *   - tool-result-pruner: 仅 compaction 触发后压历史；
16:  *   - token-guard（本插件）: read 的大结果，执行期落盘 + 头尾保留。
17:  */
18: 
19: /** Cordis 插件身份与注入。tools 提供 tools/post-execute 事件。 */
20: export const name = "token-guard";
21: export const inject = ["tools"];
22: 
23: /**
24:  * 无 schemastery 时的最小配置解析：合并默认值。
25:  * 注意：**不 export Config**——Cordis 会把导出的 Config 当作 schemastery schema 调
26:  * `.validate()`，零依赖插件无法提供，会导致加载失败。配置在 apply 内自行归一化。
27:  */
28: function normalizeConfig(input) {
29:   return {
30:     enabled: input?.enabled ?? true,
31:     readBudgetTokens: input?.readBudgetTokens ?? 4000,
32:     inlineTokens: input?.inlineTokens ?? 1500,
33:     extraTools: Array.isArray(input?.extraTools) ? input.extraTools : [],
34:   };
35: }
36: 
37: const GAP = { type: "text", text: "\n\n[... token-guard: middle pruned ...]\n\n" };
38: const CHARS_PER_TOKEN = 4;
39: 
40: /** 与 dsh-token-meter 一致的固定密度估算（粗略，仅用于判阈值，不需精确）。 */
41: function estimateText(text) {
42:   return Math.ceil(text.length / CHARS_PER_TOKEN);
43: }
44: 
45: function textBytes(text) {
46:   let bytes = 0;
47:   for (const ch of text) {
48:     const code = ch.codePointAt(0);
49:     bytes += code <= 0x7f ? 1 : code <= 0x7ff ? 2 : code <= 0xffff ? 3 : 4;
50:   }
51:   return bytes;
52: }
53: 
54: /** 保留内容只能由 text/image 块构成；含其它块就原样放过，避免破坏结构。 */
55: function retainable(content) {
56:   return Array.isArray(content) && content.every((b) => b && (b.type === "text" || b.type === "image"));
57: }
58: 
59: function priceBlock(block) {
60:   return block.type === "text" ? estimateText(block.text) + 4 : 4;
61: }
62: 
63: function priceContent(content) {
64:   return content.reduce((s, b) => s + priceBlock(b), 0);
65: }
66: 
67: /** 按 token 预算保留头尾，中间折成 GAP。返回 { head, tail, omittedBytes }。 */
68: function retainContent(content, budget) {
69:   const head = [];
70:   const tail = [];
71:   let first = 0;
72:   let last = content.length - 1;
73:   let headChars = 0;
74: 
75:   let remaining = Math.ceil(budget / 2);
76:   while (first <= last) {
77:     const block = content[first];
78:     const cost = priceBlock(block);
79:     if (cost <= remaining) { head.push(block); remaining -= cost; first++; continue; }
80:     if (block.type === "text") {
81:       const approx = Math.max(0, remaining) * CHARS_PER_TOKEN;
82:       const t = block.text.slice(0, approx);
83:       headChars = t.length;
84:       if (t.length) head.push({ type: "text", text: t });
85:     }
86:     break;
87:   }
88: 
89:   remaining = Math.floor(budget / 2);
90:   while (last >= first) {
91:     const original = content[last];
92:     const block = last === first && original.type === "text"
93:       ? { type: "text", text: original.text.slice(headChars) }
94:       : original;
95:     const cost = priceBlock(block);
96:     if (cost <= remaining) { tail.push(block); remaining -= cost; last--; continue; }
97:     if (block.type === "text") {
98:       const approx = Math.max(0, remaining) * CHARS_PER_TOKEN;
99:       const t = approx > 0 ? block.text.slice(block.text.length - approx) : "";
100:       if (t.length) tail.push({ type: "text", text: t });
101:     }
102:     break;
103:   }
104:   tail.reverse();
105: 
106:   const bytesOf = (blocks) => blocks.reduce((s, b) => s + (b.type === "text" ? textBytes(b.text) : 0), 0);
107:   return { head, tail, omittedBytes: bytesOf(content) - bytesOf(head) - bytesOf(tail) };
108: }
109: 
110: function formatNotice(omittedBytes, ref) {
111:   const locator = ref?.locator ?? "(unknown path)";
112:   const hint = ref?.retrievalHint ?? "Use read with offset/limit, or grep this path.";
113:   return `(Omitted ${omittedBytes} bytes. Full result stored at: ${locator}. ${hint})`;
114: }
115: 
116: function mergeText(blocks) {
117:   const out = [];
118:   for (const b of blocks) {
119:     const prev = out.at(-1);
120:     if (b.type === "text" && prev?.type === "text") prev.text += b.text;
121:     else out.push(b.type === "text" ? { ...b } : b);
122:   }
123:   return out;
124: }
125: 
126: function fullTextOf(content) {
127:   return content.map((b) => (b.type === "text" ? b.text : "")).join("");
128: }
129: 
130: const GREP_MATCH = /^\s*(?:Line\s+)?\d+:/;
131: const GREP_FILE_LINE = /^(.+?):(\d+):(.*)$/;
132: const PWSH_WARN = "[警告] 工具产生了大量报错输出，可能包含许多与当前修改无关的既有错误。";
133: const BUILD_CMD = /\bnpm\s+run\s+lint\b|\bnpm\s+run\s+build\b|\bnpm\s+test\b/;
134: const ERROR_LINE = /\b(?:error|err!|failed|failure|exception)\b|✖|error TS\d+/i;
135: 
136: function grepStats(text) {
137:   const counts = new Map();
138:   let matches = 0;
139:   let current = null;
140:   for (const line of text.split("\n")) {
141:     const located = line.match(GREP_FILE_LINE);
142:     if (located && !located[1].includes(" ")) {
143:       const file = located[1];
144:       counts.set(file, (counts.get(file) ?? 0) + 1);
145:       matches += 1;
146:       continue;
147:     }
148:     if (GREP_MATCH.test(line)) {
149:       matches += 1;
150:       if (current) counts.set(current, (counts.get(current) ?? 0) + 1);
151:       continue;
152:     }
153:     const header = line.trim();
154:     if (header && !header.includes(" ") && /[\\/]/.test(header)) current = header;
155:   }
156:   return { files: counts.size, matches, counts };
157: }
158: 
159: function capGrep(text) {
160:   const stats = grepStats(text);
161:   if (stats.files <= 10 && stats.matches <= 20) return null;
162:   // 无文件信息（如 "Line 3: hit"）：只报总命中数，不回灌行内容。
163:   if (stats.files === 0) {
164:     return `[token-guard] grep 命中 ${stats.matches} 条（无文件信息），请缩范围或加 include。`;
165:   }
166:   // 有文件信息：折叠为「文件清单 + 每文件命中数」，最多列 10 个文件。
167:   const entries = [...stats.counts.entries()];
168:   const shown = entries.slice(0, 10).map(([file, k]) => `${file}  (${k} 条)`);
169:   const lines = [
170:     `[token-guard] grep 命中 ${stats.matches} 条 / ${stats.files} 个文件，已折叠为文件清单（不返回行内容）。请缩范围或加 include 精确定位。`,
171:     ...shown,
172:   ];
173:   if (entries.length > 10) lines.push("...（其余文件已省略）");
174:   return lines.join("\n");
175: }
176: 
177: function capPwsh(command, text) {
178:   if (!BUILD_CMD.test(String(command || ""))) return null;
179:   const lines = text.split("\n");
180:   const errors = lines.filter((line) => ERROR_LINE.test(line));
181:   if (errors.length <= 20) return null;
182:   const omitted = lines.length - 15;
183:   return [
184:     PWSH_WARN,
185:     ...lines.slice(0, 10),
186:     `... (省略 ${omitted} 行错误) ...`,
187:     ...lines.slice(-5),
188:   ].join("\n");
189: }
190: 
191: function capOrchestrate(text) {
192:   if (text.length <= 1000 || !/无法读取|示意/.test(text)) return null;
193:   return `${text.slice(0, 1000)}\n(结果不可用，已截断。请宿主重新规划，不要沿用无法读取或示意性内容。)`;
194: }
195: 
196: /** 超限时返回截断文本；未超限返回 null。 */
197: function cappedText(exec, text) {
198:   const toolName = exec?.name;
199:   if (toolName === "grep") return capGrep(text);
200:   if (toolName === "pwsh") return capPwsh(exec?.arguments?.command, text);
201:   if (toolName === "orchestrate") return capOrchestrate(text);
202:   if (toolName === "read") {
203:     const lines = text.split("\n");
204:     const args = exec?.arguments;
205:     const hasRange = args != null && (args.offset != null || args.limit != null);
206:     if (!hasRange && lines.length > 300) {
207:       return `[token-guard] read 未带 offset/limit 且共 ${lines.length} 行（>300）。先 grep 定位，或带 offset/limit 分段读，不要整读。`;
208:     }
209:     if (hasRange && lines.length > 500) {
210:       return lines.slice(0, 500).join("\n")
211:         + "\n[token-guard] read 已超过 500 行，其余已截断。请缩小 offset/limit 范围后再读。";
212:     }
213:     return null;
214:   }
215:   if (toolName === "skill" && text.length > 2500) {
216:     return text.slice(0, 2500)
217:       + "\n[token-guard] skill 正文已截断。只保留前 2500 字，按已给出的步骤执行，不要为了补全文再整篇重读。";
218:   }
219:   return null;
220: }
221: 
222: export function apply(ctx, rawConfig) {
223:   const config = normalizeConfig(rawConfig);
224:   if (!config.enabled) return;
225:   const budget = config.inlineTokens;
226:   if (!Number.isSafeInteger(budget) || budget < 0) {
227:     throw new Error(`token-guard: inlineTokens must be a non-negative integer (got ${budget})`);
228:   }
229:   const threshold = config.readBudgetTokens;
230:   const watched = new Set(["read", ...config.extraTools]);
231: 
232:   ctx.on("tools/post-execute", async (exec, result, next) => {
233:     const decision = await next();
234:     if (decision.kind !== "accept" || Object.hasOwn(decision, "value")) return decision;
235:     let content = decision.content ?? result.content;
236:     if (!retainable(content) || content.length === 0) return decision;
237:     const shortened = cappedText(exec, fullTextOf(content));
238:     if (shortened) {
239:       content = [{ type: "text", text: shortened }];
240:       if (!watched.has(exec.name) || priceContent(content) <= threshold) {
241:         return { kind: "accept", content };
242:       }
243:     }
244:     if (!watched.has(exec.name)) return decision;
245:     if (priceContent(content) <= threshold) return decision;
246: 
247:     try {
248:       const owner = exec.agent?.session.header.id;
249:       if (owner === undefined) throw new Error(`no session owner for ${exec.name}`);
250:       const spillStore = ctx.get("spillStore");
251:       if (spillStore === undefined) throw new Error("no ctx.spillStore backend loaded");
252:       const ref = await spillStore.saveText({
253:         owner: { sessionId: owner },
254:         source: { kind: "tool", toolName: exec.name, callId: exec.callId, label: "result" },
255:         suggestedName: `${exec.name}.txt`,
256:         content: fullTextOf(content),
257:       });
258:       const retained = retainContent(content, budget);
259:       const notice = { type: "text", text: `\n\n${formatNotice(retained.omittedBytes, ref)}` };
260:       const rebuilt = retained.head.length + retained.tail.length === 0
261:         ? [notice]
262:         : mergeText([...retained.head, GAP, ...retained.tail, notice]);
263:       return { kind: "accept", content: rebuilt };
264:     } catch (error) {
265:       ctx.logger?.warn(`token-guard: ${String(error)}; keeping the inline content`);
266:       return decision;
267:     }
268:   }, { prepend: true });
269: }

