/**
 * dsh-mcp-gateway · SQL 预校验（纯函数，零依赖，可单测）
 *
 * 审计 F2（session.v4，seq 614）：模型凭记忆拼 `INSERT zt_action`，列数与 VALUES
 * 不匹配，等 MySQL 报 `Column count doesn't match` 才自愈，白烧一步。这里在**发送前**
 * 对 INSERT 做列数 vs 值数的一致性预校验，不匹配就直接返回可读错误，并点出常见漏项
 * （`files` 用 NULL、`extra` 写 'fixed'）。
 *
 * 只做「列数 == 值数」这一条确定性校验，不校验列名/类型/业务语义（那属服务端职责，
 * 猜错反而更糟）。解析不了（子查询、SELECT ... INSERT、值里含未加引号的括号等）就放行。
 */

/** 去掉 SQL 注释与字符串字面量，避免把值里的括号/逗号算进列或值分组。 */
function stripNoise(sql) {
  let out = ''
  let i = 0
  const n = sql.length
  while (i < n) {
    const ch = sql[i]
    // 单引号字符串
    if (ch === "'") {
      out += ' '
      i += 1
      while (i < n) {
        if (sql[i] === "'" && sql[i + 1] === "'") { i += 2; continue }
        if (sql[i] === "'") { i += 1; break }
        i += 1
      }
      continue
    }
    // 双引号标识符
    if (ch === '"' || ch === '`') {
      const quote = ch
      out += ' '
      i += 1
      while (i < n) {
        if (sql[i] === quote && sql[i + 1] === quote) { i += 2; continue }
        if (sql[i] === quote) { i += 1; break }
        i += 1
      }
      continue
    }
    // 行注释 --
    if (ch === '-' && sql[i + 1] === '-') {
      while (i < n && sql[i] !== '\n') i += 1
      continue
    }
    out += ch
    i += 1
  }
  return out
}

/** 按顶层逗号切分（括号深度为 0 的逗号），用于列清单与值清单。 */
function splitTopLevel(text) {
  const parts = []
  let depth = 0
  let current = ''
  for (const ch of text) {
    if (ch === '(') depth += 1
    else if (ch === ')') depth -= 1
    if (ch === ',' && depth === 0) { parts.push(current); current = ''; continue }
    current += ch
  }
  if (current.trim() !== '') parts.push(current)
  return parts
}

/** 找到匹配的右括号位置（从 open 位置的左括号起）。 */
function matchParen(text, open) {
  let depth = 0
  for (let i = open; i < text.length; i++) {
    if (text[i] === '(') depth += 1
    else if (text[i] === ')') { depth -= 1; if (depth === 0) return i }
  }
  return -1
}

const INSERT_RE = /\bINSERT\s+(?:IGNORE\s+)?INTO\s+([`"\w.]+)\s*/i

/**
 * 预校验一条 SQL。命中 INSERT 且列数 != 值数时返回错误文案；否则返回 null（放行）。
 * @param {string} sql - SQL 文本。
 * @returns {string | null}
 */
export function precheckInsert(sql) {
  if (typeof sql !== 'string' || sql === '') return null
  const clean = stripNoise(sql)
  const m = clean.match(INSERT_RE)
  if (!m) return null
  const table = m[1]
  let pos = m.index + m[0].length

  // 可选列清单
  let columnCount = null
  if (clean[pos] === '(') {
    const close = matchParen(clean, pos)
    if (close < 0) return null
    const cols = splitTopLevel(clean.slice(pos + 1, close)).filter((s) => s.trim() !== '')
    columnCount = cols.length
    pos = close + 1
  }

  // 必须有 VALUES
  const rest = clean.slice(pos)
  const valuesMatch = rest.match(/\bVALUES\b/i)
  if (!valuesMatch) return null
  const afterValues = rest.slice(valuesMatch.index + valuesMatch[0].length)
  let p = 0
  while (p < afterValues.length && /\s/.test(afterValues[p])) p += 1
  if (afterValues[p] !== '(') return null
  const vClose = matchParen(afterValues, p)
  if (vClose < 0) return null
  const values = splitTopLevel(afterValues.slice(p + 1, vClose)).filter((s) => s.trim() !== '')
  const valueCount = values.length

  if (columnCount === null) return null // 无列清单时列数由表定义决定，跳过
  if (columnCount === valueCount) return null

  const isZtAction = /zt_action/i.test(table)
  const extraHint = isZtAction
    ? '（zt_action 固定 14 列：files 写 NULL、extra 写 resolution 如 \'fixed\'、`read` 用反引号、vision 写 \'rnd\'；用 zentao-resolve.mjs 生成的模板，别手拼）'
    : ''
  return `[mcp-gateway] SQL 预校验失败：${table} 的列清单 ${columnCount} 列，VALUES ${valueCount} 个值，不一致（发送前拦截，避免 Column count doesn't match）。${extraHint}`
}

/**
 * 工具级入口：仅对 dbx 类 query 工具的 `sql` 参数预校验。
 * @param {string} server - MCP server 名。
 * @param {string} tool - 工具名。
 * @param {object} args - 工具参数。
 * @returns {string | null} 错误文案或 null。
 */
export function precheckCall(server, tool, args) {
  if (server !== 'dbx') return null
  if (typeof tool !== 'string' || !/query|execute|exec|sql/i.test(tool)) return null
  const sql = args?.sql ?? args?.statement ?? args?.query
  if (typeof sql !== 'string') return null
  return precheckInsert(sql)
}

