/** 去掉 SQL 注释，并把每个字符串字面量/引号标识符替换成占位符 `_`，
 * 既避免值里的逗号/括号干扰分组，又保持「一个值算一项」的计数。 */
function stripNoise(sql) {
  let out = ''
  let i = 0
  const n = sql.length
  while (i < n) {
    const ch = sql[i]
    // 单引号字符串
    if (ch === "'") {
      out += '_'
      i += 1
      while (i < n) {
        if (sql[i] === "'" && sql[i + 1] === "'") { i += 2; continue }
        if (sql[i] === "'") { i += 1; break }
        i += 1
      }
      continue
    }
    // 双引号 / 反引号标识符
    if (ch === '"' || ch === '`') {
      const quote = ch
      out += quote === '`' ? '`x`' : '_'
      i += 1
      while (i < n) {
        if (sql[i] === quote && sql[i + 1] === quote) { i += 2; continue }
        if (sql[i] === quote) { i += 1; break }
        i += 1
      }
      continue
    }
    // 行注释 --
    if (ch === '-' && sql[i + 1] === '-') {
      while (i < n && sql[i] !== '\n') i += 1
      continue
    }
    out += ch
    i += 1
  }
  return out
}

